}

async function buildMain() {
  // desktop/src/backend is the native backend; until it lands the stub stands in (desktop/tsconfig.json does the same).
  const backend = existsSync(path.join(desktop, "src", "backend", "index.ts")) ? "src/backend/index.ts" : "src/backend-stub.ts";
  const common = { bundle: true, platform: "node", format: "cjs", target: "node22", external: ["electron"], sourcemap: "linked", logLevel: "warning", absWorkingDir: desktop };
  await build({ ...common, entryPoints: { main: "src/main.ts" }, outdir: "dist", alias: { "#backend": `./${backend}` } });
